record.field:
for record in records:
    # === Agent 0: Bedöm allvarlighetsgrad (severity) ===
    severity_question = record.create_severity_question()
    _logger.warning(f"[AI SEVERITY] Fråga: {severity_question}")

    res_0 = agents[0].trigger_prompt( quest=quest, session=session, debug=quest.debug, message=severity_question,
    )

    extracted_severity = self.env['ai.quest'].custom_extract_json(res_0.content)
    _logger.warning(f"[AI SEVERITY] RESULTAT: {extracted_severity}")

    if extracted_severity:
        record.set_severity_level(extracted_severity)
        record._onchange_severity_level()

    # === Agent 1: Uppskatta varaktighet (duration) för varje orderrad ===
    for line in record.order_line_ids:
        duration_question = line.create_duration_question()
        _logger.warning(f"[AI DURATION] Fråga för orderrad {line.id}: {duration_question}")

        res_1 = agents[1].trigger_prompt( quest=quest, session=session, debug=quest.debug, messages=[HumanMessage(content=duration_question)],
        )

        extracted_duration = self.env['ai.quest'].custom_extract_json(res_1.content)
        _logger.warning(f"[AI DURATION] Resultat för orderrad {line.id}: {extracted_duration}")

        if extracted_duration:
            line.set_duration(extracted_duration)

    # === Agent 2: Combined Planning + Allocation ===
    planning_prompt = record.build_quest_prompt()
    _logger.warning(f"[AI PLANNING] Fråga: {planning_prompt}")

    res_2 = agents[2].trigger_prompt( quest=quest, session=session, debug=quest.debug, message=planning_prompt,
    )

    extracted_plan = self.env['ai.quest'].custom_extract_json(res_2.content)
    _logger.warning(f"[AI PLANNING] Resultat: {extracted_plan}")

    if extracted_plan:
        plan_data = extracted_plan.get(str(record.id))
        if plan_data:
            record.apply_ai_planning({str(record.id): plan_data})
            employee_id = plan_data.get("employee_id")

            if employee_id:
                for line in record.order_line_ids:
                    if line:
                        if line.fieldservice_order_line_employee_ids:
                            line.fieldservice_order_line_employee_ids[0].write({
                                'employee_id': employee_id
                            })
                            _logger.warning(f"[AI PLANNING] Uppdaterade employee_id {employee_id} för orderrad {line.id}")
                        else:
                            self.env['fieldservice.order.line.employee'].create({
                                'fieldservice_order_line_id': line.id,
                                'employee_id': employee_id,
                                'description': 'Assigned by AI'
                            })
                            _logger.warning(f"[AI PLANNING] Skapade och tilldelade employee_id {employee_id} till orderrad {line.id}")

